GlassPuntyRodMaker.ironStock=18; GlassPuntyRodMaker.bronzeStock=14; GlassPuntyRodMaker.woodStock=10; GlassPuntyRodMaker.leatherStock=8; GlassPuntyRodMaker.silverStock=8; GlassPuntyRodMaker.goldStock=6; GlassPuntyRodMaker.jewelStock=4; GlassPuntyRodMaker.pearlStock=4
