function GlassPuntyRodMaker.init() GlassPuntyRodMaker.ironStock=18; GlassPuntyRodMaker.bronzeStock=14; GlassPuntyRodMaker.woodStock=10; GlassPuntyRodMaker.leatherStock=8; GlassPuntyRodMaker.silverStock=8; GlassPuntyRodMaker.goldStock=6; GlassPuntyRodMaker.jewelStock=4; GlassPuntyRodMaker.pearlStock=4; GlassPuntyRodMaker.productStock={}; GlassPuntyRodMaker.buildings={}; GlassPuntyRodMaker.maker=nil; GlassPuntyRodMaker.activeMaking={}; GlassPuntyRodMaker.totalProducts=0; GlassPuntyRodMaker.dayTimer=0; print("[GlassPuntyRodMaker] Royal Glass Punty Rod Maker System initialized (6 products, 4 buildings)") end
function GlassPuntyRodMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassPuntyRodMaker.maker={name=n or ("Paličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Paličar najet: %s (spretnost: %d)",GlassPuntyRodMaker.maker.name,s),"success") end; return true end
function GlassPuntyRodMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassPuntyRodMaker.build(id) local ok,e=GlassPuntyRodMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassPuntyRodMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassPuntyRodMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassPuntyRodMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassPuntyRodMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassPuntyRodMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassPuntyRodMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassPuntyRodMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassPuntyRodMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassPuntyRodMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassPuntyRodMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassPuntyRodMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassPuntyRodMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassPuntyRodMaker.buildings==0 then return false,"Potrebna palična delavnica" end; if not GlassPuntyRodMaker.maker then return false,"Potreben paličar" end; return true end
function GlassPuntyRodMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassPuntyRodMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassPuntyRodMaker.ironStock=GlassPuntyRodMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassPuntyRodMaker.bronzeStock=GlassPuntyRodMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassPuntyRodMaker.woodStock=GlassPuntyRodMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassPuntyRodMaker.leatherStock=GlassPuntyRodMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassPuntyRodMaker.silverStock=GlassPuntyRodMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassPuntyRodMaker.goldStock=GlassPuntyRodMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassPuntyRodMaker.jewelStock=GlassPuntyRodMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassPuntyRodMaker.pearlStock=GlassPuntyRodMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassPuntyRodMaker.maker then t=math.max(1,t-math.floor(GlassPuntyRodMaker.maker.skill/13)) end; table.insert(GlassPuntyRodMaker.activeMaking,{id="glasspuntyrod_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassPuntyRodMaker.completeMaking(m) local q=1.0+(GlassPuntyRodMaker.getQualityBonus()/100); if GlassPuntyRodMaker.maker then q=q+(GlassPuntyRodMaker.maker.skill/140) end; q=math.min(2.5,q); GlassPuntyRodMaker.productStock[m.productType]=(GlassPuntyRodMaker.productStock[m.productType] or 0)+m.quantity; GlassPuntyRodMaker.totalProducts=GlassPuntyRodMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassPuntyRodMaker.maker then GlassPuntyRodMaker.maker.itemsMade=GlassPuntyRodMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassPuntyRodMaker.maker.skill=math.min(100,GlassPuntyRodMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasspuntyrod.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassPuntyRodMaker.update(dt) if not _G.state then return end; GlassPuntyRodMaker.dayTimer=GlassPuntyRodMaker.dayTimer+dt; if GlassPuntyRodMaker.dayTimer>=30 then GlassPuntyRodMaker.dayTimer=0; for i=#GlassPuntyRodMaker.activeMaking,1,-1 do local m=GlassPuntyRodMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassPuntyRodMaker.completeMaking(m); table.remove(GlassPuntyRodMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassPuntyRodMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassPuntyRodMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassPuntyRodMaker.getStats() return {ironStock=GlassPuntyRodMaker.ironStock,bronzeStock=GlassPuntyRodMaker.bronzeStock,woodStock=GlassPuntyRodMaker.woodStock,leatherStock=GlassPuntyRodMaker.leatherStock,silverStock=GlassPuntyRodMaker.silverStock,goldStock=GlassPuntyRodMaker.goldStock,jewelStock=GlassPuntyRodMaker.jewelStock,pearlStock=GlassPuntyRodMaker.pearlStock,productStock=GlassPuntyRodMaker.productStock,numBuildings=#GlassPuntyRodMaker.buildings,hasMaker=GlassPuntyRodMaker.maker~=nil,makerName=GlassPuntyRodMaker.maker and GlassPuntyRodMaker.maker.name or "—",makerSkill=GlassPuntyRodMaker.maker and GlassPuntyRodMaker.maker.skill or 0,activeMaking=#GlassPuntyRodMaker.activeMaking,totalProducts=GlassPuntyRodMaker.totalProducts} end
